//! 配音历史与场景对话的重新对齐。
//!
//! 配音卡关闭后场景可能被编辑, 重新打开时历史条目的行号与内容都已失效。
//! 本模块用**纯函数**完成对齐, 分两层且只做可信匹配:
//!
//! 1. **精确匹配**: 按 `(对话者, 内容)` 全等锁定, 唯一可信的一层;
//! 2. **LCS 保序匹配**: 在剩余项上求最长公共子序列, 覆盖插入/删除/移动造成的偏移。
//!
//! 低于阈值或无法匹配的条目会被明确列为 `unmatched`, 交由前端提示用户,
//! 而不是猜测性地错配到别的对话上。

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

/// 参与对齐的对话项 (由前端从 `SayLine` 简化后提交)
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DialogueKey {
    /// 对话者 (已回溯补齐), 旁白为 `None`
    pub speaker: Option<String>,
    /// 对话内容
    pub text: String,
    /// 会话内的稳定序号 (用于结果回传)
    pub index: usize,
}

/// 待对齐的历史条目
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct HistoryKey {
    /// 历史条目 id
    pub id: String,
    pub speaker: Option<String>,
    pub text: String,
}

/// 单条对齐结果
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Alignment {
    pub id: String,
    /// 匹配到的新对话序号; `None` 表示未匹配
    pub index: Option<usize>,
    /// 匹配层级
    pub kind: AlignmentKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum AlignmentKind {
    /// 对话者与内容完全一致
    Exact,
    /// 内容一致但对话者变化 (省略说话者语法导致归属漂移)
    SpeakerChanged,
    /// 保序匹配 (内容一致, 位置变化)
    Ordered,
    /// 未匹配
    Unmatched,
}

/// 对齐汇总
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AlignmentReport {
    pub alignments: Vec<Alignment>,
    pub exact: usize,
    pub speaker_changed: usize,
    pub ordered: usize,
    pub unmatched: usize,
}

/// 把历史条目对齐到新的对话列表
pub fn align(history: &[HistoryKey], dialogues: &[DialogueKey]) -> AlignmentReport {
    let mut result: Vec<Alignment> = history
        .iter()
        .map(|entry| Alignment {
            id: entry.id.clone(),
            index: None,
            kind: AlignmentKind::Unmatched,
        })
        .collect();

    // -------- 第一层: 精确匹配 (对话者 + 内容) --------
    // 同键可能对应多条对话 (重复台词), 按出现顺序依次消费
    let mut pools: HashMap<(String, String), Vec<usize>> = HashMap::new();
    for dialogue in dialogues {
        pools
            .entry((
                normalize_speaker(&dialogue.speaker),
                normalize_text(&dialogue.text),
            ))
            .or_default()
            .push(dialogue.index);
    }

    let mut taken_dialogue: Vec<bool> = vec![false; dialogues.len()];
    let mut used_positions: HashMap<usize, usize> = HashMap::new(); // 对话序号 -> 对话下标
    for (position, dialogue) in dialogues.iter().enumerate() {
        used_positions.insert(dialogue.index, position);
    }

    let mut pending: Vec<usize> = Vec::new();
    for (history_index, entry) in history.iter().enumerate() {
        let key = (
            normalize_speaker(&entry.speaker),
            normalize_text(&entry.text),
        );
        let matched = pools.get_mut(&key).and_then(|candidates| {
            while let Some(index) = candidates.first().copied() {
                candidates.remove(0);
                if let Some(&position) = used_positions.get(&index) {
                    if !taken_dialogue[position] {
                        return Some((index, position));
                    }
                }
            }
            None
        });
        match matched {
            Some((index, position)) => {
                taken_dialogue[position] = true;
                result[history_index].index = Some(index);
                result[history_index].kind = AlignmentKind::Exact;
            }
            None => pending.push(history_index),
        }
    }

    // -------- 第二层: LCS 保序匹配 --------
    let remaining_history: Vec<usize> = pending
        .iter()
        .copied()
        .filter(|&index| history[index].text.trim() != "")
        .collect();
    let remaining_dialogue: Vec<usize> = dialogues
        .iter()
        .enumerate()
        .filter(|(position, _)| !taken_dialogue[*position])
        .map(|(_, dialogue)| dialogue.index)
        .collect();

    let lcs = longest_common_subsequence(
        history,
        dialogues,
        &remaining_history,
        &remaining_dialogue,
        &used_positions,
    );

    for (history_index, dialogue_index) in lcs {
        let entry = &history[history_index];
        if let Some(&position) = used_positions.get(&dialogue_index) {
            taken_dialogue[position] = true;
        }
        // 内容一致但对话者不同 -> 标为归属漂移, 让前端决定是否采用
        let dialogue = dialogues
            .iter()
            .find(|dialogue| dialogue.index == dialogue_index)
            .expect("对话序号必然存在");
        let same_speaker =
            normalize_speaker(&entry.speaker) == normalize_speaker(&dialogue.speaker);
        result[history_index].index = Some(dialogue_index);
        result[history_index].kind = if same_speaker {
            AlignmentKind::Ordered
        } else {
            AlignmentKind::SpeakerChanged
        };
    }

    let count = |kind: AlignmentKind| result.iter().filter(|item| item.kind == kind).count();
    AlignmentReport {
        exact: count(AlignmentKind::Exact),
        speaker_changed: count(AlignmentKind::SpeakerChanged),
        ordered: count(AlignmentKind::Ordered),
        unmatched: count(AlignmentKind::Unmatched),
        alignments: result,
    }
}

/// 以内容为键的最长公共子序列 (保序)
fn longest_common_subsequence(
    history: &[HistoryKey],
    dialogues: &[DialogueKey],
    history_indices: &[usize],
    dialogue_indices: &[usize],
    used_positions: &HashMap<usize, usize>,
) -> Vec<(usize, usize)> {
    let n = history_indices.len();
    let m = dialogue_indices.len();
    if n == 0 || m == 0 {
        return Vec::new();
    }

    let text_of_dialogue = |index: usize| -> String {
        let position = used_positions[&index];
        normalize_text(&dialogues[position].text)
    };
    let text_of_history = |index: usize| normalize_text(&history[index].text);

    let mut lengths = vec![vec![0u32; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            lengths[i][j] =
                if text_of_history(history_indices[i]) == text_of_dialogue(dialogue_indices[j]) {
                    lengths[i + 1][j + 1] + 1
                } else {
                    lengths[i + 1][j].max(lengths[i][j + 1])
                };
        }
    }

    let mut pairs = Vec::new();
    let (mut i, mut j) = (0usize, 0usize);
    while i < n && j < m {
        if text_of_history(history_indices[i]) == text_of_dialogue(dialogue_indices[j]) {
            pairs.push((history_indices[i], dialogue_indices[j]));
            i += 1;
            j += 1;
        } else if lengths[i + 1][j] >= lengths[i][j + 1] {
            i += 1;
        } else {
            j += 1;
        }
    }
    pairs
}

fn normalize_speaker(speaker: &Option<String>) -> String {
    speaker.as_deref().unwrap_or("").trim().to_string()
}

fn normalize_text(text: &str) -> String {
    text.trim().to_string()
}

